<?php
namespace App\Http\Controllers;
use App\Models\Employee; use App\Models\Unit; use App\Models\WorkforceDemandInput; use App\Models\WorkforceDemandRule; use App\Services\WorkforceAuditService; use Carbon\Carbon; use Illuminate\Http\Request;
class DemandForecastController extends Controller {
 public function index(Request $r){$from=Carbon::parse($r->query('from',now()->subDays(27)->toDateString()));$to=Carbon::parse($r->query('to',now()->toDateString()));$rules=WorkforceDemandRule::with(['unit','position'])->where('is_active',true)->get();$rows=$rules->map(function($rule)use($from,$to){$avg=(float)WorkforceDemandInput::where('unit_id',$rule->unit_id)->where('metric',$rule->demand_metric)->whereBetween('period_date',[$from,$to])->avg('value');$required=max((float)$rule->minimum_fte,$rule->units_per_fte>0?$avg/(float)$rule->units_per_fte:0);$actual=Employee::where('is_active',true)->where('unit_id',$rule->unit_id)->when($rule->position_id,fn($q)=>$q->where('position_id',$rule->position_id))->count();return ['rule'=>$rule,'average_demand'=>round($avg,2),'required_fte'=>round($required,2),'actual_headcount'=>$actual,'gap'=>round($actual-$required,2)];});return view('workforce.demand.index',compact('rules','rows','from','to'));}
 public function storeRule(Request $r,WorkforceAuditService $audit){$d=$r->validate(['unit_id'=>'required|exists:units,id','position_id'=>'nullable|exists:positions,id','demand_metric'=>'required|in:patient_visits,admissions,bed_days,theatre_cases,clinic_visits,lab_tests,custom','units_per_fte'=>'required|numeric|gt:0','minimum_fte'=>'required|numeric|min:0']);$d['updated_by']=auth()->id();$m=WorkforceDemandRule::updateOrCreate(['unit_id'=>$d['unit_id'],'position_id'=>$d['position_id']??null,'demand_metric'=>$d['demand_metric']],$d+['is_active'=>true]);$audit->model('updated',$m,'Workforce demand rule saved');return back()->with('success','Demand rule saved.');}
 public function storeInput(Request $r,WorkforceAuditService $audit){$d=$r->validate(['unit_id'=>'required|exists:units,id','period_date'=>'required|date','metric'=>'required|string|max:40','value'=>'required|numeric|min:0','source_reference'=>'nullable|string|max:180']);$d['source']='manual';$d['recorded_by']=auth()->id();$m=WorkforceDemandInput::updateOrCreate(['unit_id'=>$d['unit_id'],'period_date'=>$d['period_date'],'metric'=>$d['metric'],'source'=>'manual'],$d);$audit->model('updated',$m,'Workforce demand input saved');return back()->with('success','Demand input saved.');}
}
